<?php
namespace app\controller;
use app\BaseController; use app\service\AdminAccess; use app\service\RedisService;use think\facade\Db;use think\facade\Session;use think\facade\View;
class Admin extends BaseController{
 private function audit($action,$detail=''){Db::name('audit_logs')->insert(['admin_id'=>Session::get('lumen_admin_id')?:null,'action'=>$action,'target_type'=>'admin','target_id'=>Session::get('lumen_admin_id')?:null,'detail'=>$detail,'ip'=>request()->ip(),'created_at'=>date('Y-m-d H:i:s')]);}
 public function login(){return redirect('/admin');}
 public function authenticate(){if(!is_file(root_path().'storage/install/install.lock'))return redirect('/install');$ip=request()->ip();$u=trim((string)input('post.username',''));$p=(string)input('post.password','');$since=date('Y-m-d H:i:s',time()-600);$fails=Db::name('audit_logs')->where('action','admin.login_failed')->where('ip',$ip)->where('created_at','>=',$since)->count();if($fails>=8){View::assign('installed',false);View::assign('error','登录失败次数过多，请 10 分钟后再试。');return View::fetch(root_path().'view/admin/login.html');}$a=Db::name('admins')->where('username',$u)->where('status',1)->find();if(!$a||!password_verify($p,$a['password_hash'])){Db::name('audit_logs')->insert(['admin_id'=>null,'action'=>'admin.login_failed','target_type'=>'admin','target_id'=>null,'detail'=>'username='.mb_substr($u,0,32),'ip'=>$ip,'created_at'=>date('Y-m-d H:i:s')]);View::assign('installed',false);View::assign('error','用户名或密码错误。');return View::fetch(root_path().'view/admin/login.html');}Session::clear();Session::regenerate(true);Session::set('lumen_admin_id',(int)$a['id']);Session::set('lumen_admin_username',$a['username']);Session::set('lumen_admin_role',(string)($a['role']??'admin'));Db::name('admins')->where('id',$a['id'])->update(['last_login_at'=>date('Y-m-d H:i:s'),'last_login_ip'=>$ip,'updated_at'=>date('Y-m-d H:i:s')]);$this->audit('admin.login','success');return redirect('/admin');}
 public function dashboard(){if(!is_file(root_path().'storage/install/install.lock'))return redirect('/install');if(!AdminAccess::current()){View::assign('installed',input('get.installed','')==='1');View::assign('error','');return View::fetch(root_path().'view/admin/login.html');}try{\think\facade\Db::query('SELECT 1 FROM `api_users` LIMIT 0');}catch(\Throwable $e){return response('LumenAPI 安装不完整：缺少业务数据库表。管理员账号已保留，请先补齐数据库迁移文件。',503);} $today=date('Y-m-d 00:00:00');$total=Db::name('request_logs')->count();$todayCount=Db::name('request_logs')->where('created_at','>=',$today)->count();$errors=Db::name('request_logs')->where('created_at','>=',$today)->where('status_code','>=',400)->count();$avg=(int)(Db::name('request_logs')->where('created_at','>=',$today)->avg('duration_ms')?:0);View::assign(['username'=>Session::get('lumen_admin_username'),'endpointCount'=>Db::name('endpoints')->count(),'enabledEndpointCount'=>Db::name('endpoints')->where('status',1)->count(),'requestCount'=>$total,'todayRequestCount'=>$todayCount,'todayErrorCount'=>$errors,'avgDuration'=>$avg,'keyCount'=>Db::name('keys')->count(),'activeKeyCount'=>Db::name('keys')->where('status',1)->count(),'auditCount'=>Db::name('audit_logs')->count(),'recent'=>Db::name('request_logs')->alias('r')->leftJoin('endpoints e','e.id=r.endpoint_id')->field('r.*,e.name endpoint_name')->order('r.id','desc')->limit(8)->select()->toArray()]);View::assign('redisStatus',RedisService::status());return View::fetch(root_path().'view/admin/dashboard.html');}
 public function logout(){if(Session::has('lumen_admin_id'))$this->audit('admin.logout','');Session::clear();return redirect('/admin');}
}
